# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Use safety gating, confidence hysteresis, and target-bearing steering.

    The controller keeps only a few scalar/string fields in memory, holds
    briefly after target loss, and reuses a compatible steering command inside
    a deadband to reduce oscillation and unnecessary instruction changes.
    """
    memory = dict(memory or {})

    state = memory.get("state", "IDLE")
    scan_direction = memory.get("scan_direction", "SCAN_LEFT")
    last_action = memory.get("last_action", "")
    stable_steps = int(memory.get("stable_steps", 0))

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    target_confidence = float(observation["target_confidence"])
    identity_confidence = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost_steps = int(observation["lost_steps"])
    safety_confidence = float(observation["safety_confidence"])
    closing_risk = float(observation["closing_risk"])

    def emit(action, confidence, next_state):
        memory["state"] = next_state
        memory["last_action"] = action
        memory["stable_steps"] = stable_steps + 1 if action == last_action else 1
        return action, confidence, memory

    # Hard safety gate.
    if safety_confidence < 0.60 or closing_risk >= 0.75:
        return emit("STOP", 0.99, "STOPPED")

    # Require a sufficiently reliable target before moving.
    reliable = (
        visible
        and target_confidence >= 0.55
        and identity_confidence >= 0.60
    )
    if not reliable:
        if state in {"LOCKED", "APPROACH", "REACQUIRE"} or lost_steps > 0:
            memory["state"] = "REACQUIRE"
            if lost_steps <= 1:
                return emit("STOP", 0.92, "REACQUIRE")

        action = scan_direction
        memory["scan_direction"] = (
            "SCAN_RIGHT" if scan_direction == "SCAN_LEFT" else "SCAN_LEFT"
        )
        return emit(action, 0.74, "SEARCH")

    # Confirm newly acquired tracks before committing to forward motion.
    if track_age < 2:
        return emit("SLOW_DOWN", 0.82, "VERIFY")

    heading_error = abs(float(observation["heading_error"]))

    # Arrival is accepted only for a close, well-aligned, strongly identified target.
    if (
        distance == "near"
        and heading_error <= 15.0
        and abs(bearing) <= 12.0
        and identity_confidence >= 0.80
    ):
        return emit("ARRIVED", 0.96, "ARRIVED")

    memory["state"] = "APPROACH"

    left_open = bool(observation["corridor_left"])
    right_open = bool(observation["corridor_right"])
    center_open = bool(observation["corridor_center"])

    # Use a wider deadband when already steering, preventing rapid left/right flips.
    steer_limit = 12.0 if last_action not in {"VEER_LEFT", "VEER_RIGHT"} else 16.0
    desired = ""
    if bearing < -steer_limit:
        desired = "VEER_LEFT"
    elif bearing > steer_limit:
        desired = "VEER_RIGHT"

    # Preserve a compatible turn for small bearing noise, but never persist through
    # a clearly reversed target direction.
    if not desired and abs(bearing) <= steer_limit:
        if last_action == "VEER_LEFT" and left_open and bearing > -24.0:
            desired = "VEER_LEFT"
        elif last_action == "VEER_RIGHT" and right_open and bearing < 24.0:
            desired = "VEER_RIGHT"

    if desired == "VEER_LEFT" and left_open:
        return emit("VEER_LEFT", 0.89, "APPROACH")
    if desired == "VEER_RIGHT" and right_open:
        return emit("VEER_RIGHT", 0.89, "APPROACH")

    if center_open:
        return emit("FORWARD", 0.91, "APPROACH")
    if bearing < 0.0 and left_open:
        return emit("VEER_LEFT", 0.82, "APPROACH")
    if bearing > 0.0 and right_open:
        return emit("VEER_RIGHT", 0.82, "APPROACH")
    if left_open:
        return emit("VEER_LEFT", 0.78, "APPROACH")
    if right_open:
        return emit("VEER_RIGHT", 0.78, "APPROACH")

    return emit("STOP", 0.98, "STOPPED")
# EVOLVE-BLOCK-END
